import React, { useState } from "react";
import { toast } from "react-hot-toast";
import { completeTask, submitDay as submitDayAPI, regeneratePlan } from "../../../api/planApi";
import UIModal from "../../common/UIModal";

const DashboardOverview = ({ user, goal, plan, setView, summary, latestJournal, subscription, onUpdate }) => {
    const [loading, setLoading] = useState(false);
    const [modal, setModal] = useState({
        isOpen: false,
        type: "alert", // alert, confirm, prompt
        title: "",
        message: "",
        onConfirm: () => { },
        isLoading: false
    });

    const closeModal = () => setModal(prev => ({ ...prev, isOpen: false }));

    // Motivation from AI - clean up common AI formatting symbols
    const cleanMotivation = (plan?.dailyMotivation || "Your consistency is elite! Keep crushing those goals - you're making steady progress. 🚀")
        .replace(/\*\*/g, '')
        .replace(/\*\(.*?\)\*/g, '') // Remove italicized reasoning like *(Reasoning)*
        .replace(/^\s*\*|\*\s*$/g, '') // Remove standalone italics markers
        .replace(/^["']|["']$/g, '')
        .replace(/"/g, '') // Aggressively remove ALL double quotes
        .trim();

    const handleRegenerate = async (feedback) => {
        setModal(prev => ({ ...prev, isLoading: true }));
        try {
            await regeneratePlan(feedback);
            onUpdate();
            closeModal();
            toast?.success("Plan Refreshed! 🔄");
        } catch (error) {
            closeModal(); // Close prompt
            // Show error modal
            setModal({
                isOpen: true,
                type: "alert",
                title: "Error",
                message: "Failed to regenerate plan. Please try again.",
                onConfirm: () => closeModal()
            });
        }
    };

    // ... (omitting unchanged methods for brevity in tool call, sticking to one replace block per call usually safer but I need to replace separate blocks. I will use multi_replace for clarity.)

    // Actually, I can use multi_replace.
    // Block 1: handleRegenerate toast.
    // Block 2: Free Plan badge.

    // Returning for separate tool call or single replace if contiguous. They are not contiguous.
    // multi_replace is safer.

    // Local state for optimistic updates
    const [optimisticTasks, setOptimisticTasks] = useState(null);

    // Sync optimistic tasks when plan changes
    React.useEffect(() => {
        if (plan?.tasks) {
            setOptimisticTasks(plan.tasks);
        }
    }, [plan?.tasks]);

    const handleToggleTask = async (taskId) => {
        if (plan?.status === "SUBMITTED") {
            toast?.error("This day is finalized.");
            return;
        }

        // Optimistic Update
        const previousTasks = [...optimisticTasks];
        const newTasks = optimisticTasks.map(t =>
            t._id === taskId ? { ...t, isCompleted: !t.isCompleted } : t
        );
        setOptimisticTasks(newTasks);

        try {
            await completeTask(plan._id, taskId);
            // Sync with parent (silent fetch)
            onUpdate();
        } catch (error) {
            // Revert on error
            setOptimisticTasks(previousTasks);
            toast?.error("Failed to update task. Reverting...");
            console.error(error);
        }
    };

    // Use optimisticTasks for rendering if available
    const displayTasks = optimisticTasks || plan?.tasks || [];

    const handleFinishDay = async () => {
        setModal(prev => ({ ...prev, isLoading: true }));
        try {
            await submitDayAPI();
            onUpdate();
            closeModal();
            // User specifically requested NO Alerts or popups after successful completion
        } catch (error) {
            closeModal();
            setModal({
                isOpen: true,
                type: "alert",
                title: "Error",
                message: "Failed to finish day. Please try again.",
                onConfirm: () => closeModal()
            });
        }
    };

    const openFinishDayModal = () => {
        setModal({
            isOpen: true,
            type: "confirm",
            title: "Finish Day?",
            message: "This will lock today's progress and roll over any pending tasks to tomorrow. Are you sure?",
            confirmText: "Yes, Finish Day",
            onConfirm: handleFinishDay
        });
    };

    const openRegenerateModal = () => {
        setModal({
            isOpen: true,
            type: "prompt",
            title: "Regenerate Plan",
            message: "Tell the AI what you'd like to change about this plan (e.g. 'More coding', 'Less math').",
            inputPlaceholder: "I have more time today...",
            confirmText: "Regenerate",
            onConfirm: (feedback) => handleRegenerate(feedback)
        });
    };

    const calculateProgress = () => {
        if (displayTasks.length === 0) return 0;
        const completed = displayTasks.filter(t => t.isCompleted).length;
        return Math.round((completed / displayTasks.length) * 100);
    };

    const stats = {
        completed: displayTasks.filter(t => t.isCompleted).length || 0,
        total: displayTasks.length || 0,
        percentage: calculateProgress(),
    };

    const getGreeting = () => {
        const hour = new Date().getHours();
        if (hour < 12) return "Good Morning";
        if (hour < 18) return "Good Afternoon";
        return "Good Evening";
    };

    return (
        <div className="space-y-6 pb-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <UIModal
                isOpen={modal.isOpen}
                type={modal.type}
                title={modal.title}
                message={modal.message}
                onConfirm={modal.onConfirm}
                onClose={closeModal}
                isLoading={modal.isLoading}
                confirmText={modal.confirmText}
                inputPlaceholder={modal.inputPlaceholder}
            />

            {!goal ? (
                <div className="bg-user-card p-12 rounded-2xl border border-user-sidebar shadow-sm text-center space-y-6">
                    <div className="w-16 h-16 bg-user-bg text-user-text rounded-full flex items-center justify-center text-3xl mx-auto ring-8 ring-user-bg/50">
                        <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                        </svg>
                    </div>
                    <div>
                        <h2 className="text-2xl font-semibold text-user-text mb-2">Configure Your Objective</h2>
                        <p className="text-sm text-user-text/80 max-w-sm mx-auto">Establish your primary goal and let our AI create a structured roadmap.</p>
                    </div>
                    <button
                        onClick={() => setView("goal-setup")}
                        className="bg-user-text text-user-card px-8 py-3 rounded-xl font-medium hover:bg-user-hover hover:text-gray-900 transition-colors shadow-sm"
                    >
                        Set Your Goal
                    </button>
                </div>
            ) : !plan ? (
                <div className="bg-user-card p-12 rounded-2xl border border-user-sidebar shadow-sm text-center space-y-6">
                    <div className="w-16 h-16 bg-user-bg text-user-text rounded-full flex items-center justify-center text-3xl mx-auto ring-8 ring-user-bg/50">
                        <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                    </div>
                    <div>
                        <h2 className="text-2xl font-semibold text-user-text mb-2">No Active Plan</h2>
                        <p className="text-sm text-user-text/80 max-w-sm mx-auto">Generate your structured daily plan to begin your tasks.</p>
                    </div>
                    <button
                        onClick={() => setView("daily-plan")}
                        className="bg-user-text text-user-card px-8 py-3 rounded-xl font-medium hover:bg-user-hover hover:text-gray-900 transition-colors shadow-sm"
                    >
                        Generate Daily Plan
                    </button>
                </div>
            ) : (
                <div className="space-y-6">
                    {/* 1. Header Section (Clean Professional Style) */}
                    <div className="bg-user-card p-8 rounded-2xl border border-user-sidebar shadow-sm relative overflow-hidden flex flex-col md:flex-row md:items-center justify-between gap-8">
                        <div className="relative z-10 space-y-3 max-w-2xl">
                            <div>
                                <h1 className="text-3xl font-bold text-user-text leading-tight">
                                    {getGreeting()}, {user?.name?.split(' ')[0] || 'User'}
                                </h1>
                                <p className="text-sm text-user-text/80 mt-2 flex items-center gap-2">
                                    <svg className="w-4 h-4 text-user-text/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                    </svg>
                                    {new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
                                </p>
                            </div>

                            <div className="pt-4 mt-4 border-t border-user-sidebar/50">
                                <p className="text-base text-user-text leading-relaxed italic border-l-4 border-user-text/50 pl-4">
                                    "{cleanMotivation}"
                                </p>
                            </div>
                        </div>

                        {/* Active Mission Card */}
                        {goal && (
                            <div className="bg-user-bg/50 p-5 rounded-xl border border-user-sidebar flex flex-col items-start min-w-[240px]">
                                <div className="flex items-center gap-3 mb-3">
                                    <div className="w-10 h-10 bg-user-card rounded-lg flex items-center justify-center text-primary shadow-sm border border-user-sidebar">
                                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                                        </svg>
                                    </div>
                                    <div>
                                        <p className="text-xs font-semibold text-user-text/80 uppercase tracking-wider">Current Goal</p>
                                        <p className="font-semibold text-user-text line-clamp-1">{goal.title}</p>
                                    </div>
                                </div>
                                <div className="w-full px-3 py-1.5 bg-user-card rounded-md border border-user-sidebar text-xs font-medium text-user-text/80 flex items-center gap-2">
                                    <span className="w-2 h-2 rounded-full bg-blue-500"></span>
                                    {goal.target || "On Track"}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* 3. Today's Daily Plan (Tasks) */}
                    <div className="bg-user-card rounded-2xl border border-user-sidebar shadow-sm p-8">
                        {/* Header with Progress */}
                        <div className="flex items-center justify-between mb-6 pb-6 border-b border-user-sidebar/50">
                            <div>
                                <h2 className="text-xl font-bold text-user-text">Today's Tasks</h2>
                                <p className="text-sm text-user-text/80 mt-1">
                                    {stats.completed} of {stats.total} completed
                                </p>
                            </div>
                            <div className="flex items-center gap-4">
                                <div className="hidden md:block w-32">
                                    <div className="flex justify-between text-xs text-user-text/80 mb-1">
                                        <span>Progress</span>
                                        <span className="font-semibold text-user-text">{stats.percentage}%</span>
                                    </div>
                                    <div className="h-2 w-full bg-user-sidebar rounded-full overflow-hidden">
                                        <div className="h-full bg-user-text transition-all duration-500" style={{ width: `${stats.percentage}%` }}></div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Task List */}
                        <div className="space-y-4">
                            {displayTasks.map((task) => (
                                <div
                                    key={task._id}
                                    className={`group relative flex items-start sm:items-center p-4 rounded-xl border transition-all ${task.isCompleted
                                        ? "bg-user-bg/30 border-user-sidebar/60 opacity-80"
                                        : "bg-user-card border-user-sidebar hover:border-user-text"
                                        }`}
                                >
                                    <div className="relative pt-1 sm:pt-0">
                                        <input
                                            type="checkbox"
                                            checked={task.isCompleted}
                                            onChange={() => handleToggleTask(task._id)}
                                            disabled={loading || plan.status === "SUBMITTED"}
                                            className={`w-6 h-6 rounded border-user-sidebar focus:ring-user-hover focus:ring-offset-0 transition-all ${plan.status === "SUBMITTED" ? "text-user-sidebar cursor-not-allowed" : "text-user-text cursor-pointer"}`}
                                        />
                                    </div>

                                    <div className="ml-4 flex-1">
                                        <div className="flex flex-wrap items-center gap-2 mb-1">
                                            <span className={`px-2.5 py-0.5 rounded text-xs font-semibold ${task.isCompleted ? "bg-user-bg/50 text-user-text/60" : "bg-user-bg text-user-text"
                                                }`}>
                                                {task.skill}
                                            </span>
                                            <span className="text-xs text-user-text/80 flex items-center gap-1">
                                                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                                                </svg>
                                                {task.duration} min
                                            </span>
                                            {!task.isCompleted && plan.status === "SUBMITTED" ? (
                                                <span className="px-2 py-0.5 ml-auto text-[10px] font-bold uppercase tracking-wider bg-user-modal text-user-text border-user-text rounded-md">
                                                    Carried Forward
                                                </span>
                                            ) : task.isRolledOver && !task.isCompleted && plan.status !== "SUBMITTED" ? (
                                                <span className="px-2 py-0.5 ml-auto text-[10px] font-bold uppercase tracking-wider bg-user-modal text-user-text border-user-text rounded-md">
                                                    Rolled Over
                                                </span>
                                            ) : null}
                                        </div>
                                        <p className={`text-base font-medium transition-all ${task.isCompleted ? "text-user-text/50 line-through" : "text-user-text"
                                            }`}>
                                            {task.task}
                                        </p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* 4. Actions Grid */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                        <button onClick={() => setView("daily-plan")} className="flex items-center justify-center gap-2 py-3.5 px-4 bg-user-card hover:bg-user-hover text-user-text rounded-xl border border-user-sidebar transition-colors font-semibold text-sm shadow-sm">
                            <svg className="w-4 h-4 text-user-text/80" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                            </svg>
                            Full Scope
                        </button>
                        <button onClick={openRegenerateModal} disabled={loading || plan?.status === "SUBMITTED"} className="flex items-center justify-center gap-2 py-3.5 px-4 bg-user-card hover:bg-user-hover text-user-text rounded-xl border border-user-sidebar transition-colors font-semibold text-sm shadow-sm disabled:opacity-50 disabled:cursor-not-allowed">
                            <svg className="w-4 h-4 text-user-text/80" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                            </svg>
                            Regenerate
                        </button>
                        {plan.status !== "SUBMITTED" ? (
                            <button onClick={openFinishDayModal} disabled={loading} className="flex items-center justify-center gap-2 py-3.5 px-4 bg-user-text hover:bg-user-hover hover:text-gray-900 text-user-card rounded-xl shadow-sm transition-colors font-semibold text-sm border border-transparent">
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" />
                                </svg>
                                Finish Day
                            </button>
                        ) : (
                            <div className="flex items-center justify-center gap-2 py-3.5 px-4 bg-user-sidebar text-user-text rounded-xl border border-user-text font-semibold text-sm">
                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                                </svg>
                                Completed
                            </div>
                        )}
                        <button onClick={() => setView("progress")} className="flex items-center justify-center gap-2 py-3.5 px-4 bg-user-card hover:bg-user-hover text-user-text rounded-xl border border-user-sidebar transition-colors font-semibold text-sm shadow-sm">
                            <svg className="w-4 h-4 text-user-text/80" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                            </svg>
                            Metrics
                        </button>
                    </div>

                </div>
            )}
        </div>
    );
};

export default DashboardOverview;
