import React, { useState, useEffect } from "react";
import { toast } from "react-hot-toast";
import { createEntry, getEntries } from "../../../api/journalApi";
import UIModal from "../../common/UIModal";

const JournalView = ({ onUpdate }) => {
    const [content, setContent] = useState("");
    const [loading, setLoading] = useState(false);
    const [entries, setEntries] = useState([]);
    const [sentiment, setSentiment] = useState(null);
    const [sentimentSkipped, setSentimentSkipped] = useState(false);
    const [errorModal, setErrorModal] = useState({ isOpen: false, message: "" });

    const fetchEntries = async () => {
        try {
            const res = await getEntries();
            setEntries(res.data);
        } catch (error) {
            console.error("Failed to fetch journals", error);
        }
    };

    useEffect(() => {
        fetchEntries();
    }, []);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!content.trim()) return;
        setLoading(true);
        try {
            const res = await createEntry(content);
            setSentiment(res.data.sentiment);
            setSentimentSkipped(res.data.sentimentSkipped || false);
            setContent("");
            fetchEntries();
            if (onUpdate) onUpdate();

            if (res.data.sentimentSkipped) {
                toast("Journal saved. AI limit reached for this month.", {
                    icon: '📝',
                    style: {
                        borderRadius: '10px',
                        background: '#333',
                        color: '#fff',
                    },
                });
            } else {
                toast.success("Reflection analyzed!");
            }
        } catch (error) {
            setErrorModal({
                isOpen: true,
                message: "Failed to save entry: " + (error.response?.data?.message || error.message)
            });
        } finally {
            setLoading(false);
        }
    };

    const getSentimentEmoji = (s) => {
        switch (s?.toLowerCase()) {
            case 'motivated': return '🔥';
            case 'neutral': return '😐';
            case 'stressed': return '😰';
            case 'demotivated': return '📉';
            default: return '🧠';
        }
    };

    return (
        <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-12">
            <UIModal
                isOpen={errorModal.isOpen}
                onClose={() => setErrorModal({ ...errorModal, isOpen: false })}
                type="alert"
                title="Journal Error"
                message={errorModal.message}
                onConfirm={() => setErrorModal({ ...errorModal, isOpen: false })}
            />
            <div className="bg-user-card p-8 md:p-10 rounded-2xl shadow-sm border border-user-sidebar">
                <div className="mb-8 pb-6 border-b border-user-sidebar/50">
                    <h2 className="text-3xl font-bold text-user-text flex items-center gap-3">
                        <div className="w-10 h-10 bg-user-bg text-user-text rounded-xl flex items-center justify-center border border-user-sidebar">
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                            </svg>
                        </div>
                        Daily Reflection
                    </h2>
                    <p className="text-sm font-medium text-user-text/80 mt-2 ml-14">
                        Document your thoughts, log your progress, and get AI insights.
                    </p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="relative">
                        <textarea
                            className="w-full rounded-xl border border-user-sidebar bg-user-card focus:border-user-hover focus:ring-1 focus:ring-user-hover p-6 text-base font-medium transition-all min-h-[200px] shadow-sm resize-y text-user-text"
                            placeholder="How was your learning today? What felt challenging?"
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                        />
                        <div className="absolute bottom-4 right-4 flex items-center gap-1.5 opacity-60">
                            <svg className="w-3.5 h-3.5 text-user-text" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                            </svg>
                            <span className="text-xs font-semibold text-user-text uppercase tracking-widest">AI Analysis</span>
                        </div>
                    </div>

                    <div className="flex flex-col sm:flex-row items-center justify-between gap-4 pt-4">
                        {sentiment && (
                            <div className={`flex items-center gap-3 p-3 rounded-lg border animate-in zoom-in duration-500 ${sentimentSkipped ? 'bg-amber-50 border-amber-200' : 'bg-blue-50 border-blue-200'}`}>
                                <div className="text-2xl">{getSentimentEmoji(sentiment)}</div>
                                <div>
                                    <p className={`text-[10px] font-semibold uppercase tracking-wider mb-0.5 ${sentimentSkipped ? 'text-amber-600' : 'text-blue-600'}`}>
                                        {sentimentSkipped ? 'Limit Reached' : 'Detected State'}
                                    </p>
                                    <p className={`text-sm font-bold capitalize ${sentimentSkipped ? 'text-amber-900' : 'text-blue-900'}`}>
                                        {sentimentSkipped ? 'Saved (No AI)' : sentiment}
                                    </p>
                                </div>
                            </div>
                        )}
                        {!sentiment && <div className="flex-1"></div>}
                        <button
                            type="submit"
                            disabled={loading || !content.trim()}
                            className="bg-user-text hover:bg-user-hover text-user-card hover:text-gray-900 py-3.5 px-8 rounded-xl font-semibold text-sm transition-colors shadow-sm disabled:opacity-50 w-full sm:w-auto ml-auto border border-transparent hover:border-user-text"
                        >
                            {loading ? "Analyzing..." : "Reflect & Save"}
                        </button>
                    </div>
                </form>
            </div>

            <div className="space-y-6 pt-4">
                <h3 className="text-xl font-bold text-user-text">Previous Reflections</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {entries.map((entry) => (
                        <div key={entry._id} className="bg-user-card p-6 rounded-2xl border border-user-sidebar hover:border-user-text shadow-sm transition-colors group">
                            <div className="flex justify-between items-start mb-4">
                                <div className="flex items-center gap-2">
                                    <svg className="w-4 h-4 text-user-text/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                    </svg>
                                    <span className="text-sm font-semibold text-user-text/80">
                                        {new Date(entry.date).toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' })}
                                    </span>
                                </div>
                                <div className="w-8 h-8 flex items-center justify-center text-xl bg-user-bg/50 rounded-lg border border-user-sidebar/50">
                                    {getSentimentEmoji(entry.sentiment)}
                                </div>
                            </div>
                            <p className="text-sm font-medium text-user-text leading-relaxed line-clamp-4">
                                {entry.content}
                            </p>
                        </div>
                    ))}
                    {entries.length === 0 && (
                        <div className="col-span-full py-16 bg-user-bg/20 rounded-2xl border border-dashed border-user-sidebar text-center flex flex-col items-center">
                            <svg className="w-10 h-10 text-user-text/50 mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                            </svg>
                            <p className="text-sm font-medium text-user-text/70">No reflections yet. Start your journey today.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default JournalView;
