import React, { useState } from "react";
import { acceptGoal, regenerateGoalPlan } from "../../../api/goalApi";
import UIModal from "../../common/UIModal";

const SummaryPlanView = ({ goal, onAccepted }) => {
    const [loading, setLoading] = useState(false);
    const [regeneratePrompt, setRegeneratePrompt] = useState("");
    const [showRegenerateInput, setShowRegenerateInput] = useState(false);
    const [errorModal, setErrorModal] = useState({ isOpen: false, message: "" });

    const handleAccept = async () => {
        setLoading(true);
        try {
            await acceptGoal(goal._id);
            onAccepted();
        } catch (error) {
            setErrorModal({
                isOpen: true,
                message: "Failed to accept plan: " + (error.response?.data?.message || error.message)
            });
        } finally {
            setLoading(false);
        }
    };

    const handleRegenerate = async () => {
        setLoading(true);
        try {
            await regenerateGoalPlan(goal._id, regeneratePrompt);
            onAccepted(); // Refresh data to see new summary
            setShowRegenerateInput(false);
            setRegeneratePrompt("");
        } catch (error) {
            setErrorModal({
                isOpen: true,
                message: "Failed to regenerate plan: " + (error.response?.data?.message || error.message)
            });
        } finally {
            setLoading(false);
        }
    };

    const summary = goal.summaryPlan || {};

    return (
        <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <UIModal
                isOpen={errorModal.isOpen}
                onClose={() => setErrorModal({ ...errorModal, isOpen: false })}
                type="alert"
                title="Goal Error"
                message={errorModal.message}
                onConfirm={() => setErrorModal({ ...errorModal, isOpen: false })}
            />
            <div className="bg-user-card p-8 md:p-10 rounded-2xl shadow-sm border border-user-sidebar">
                <div className="mb-8 border-b border-user-sidebar pb-8">
                    <div className="inline-flex items-center px-3 py-1 bg-user-bg/50 text-user-text rounded-md text-xs font-semibold mb-3">
                        Strategic Roadmap
                    </div>
                    <h2 className="text-3xl font-bold text-user-text leading-tight mb-2">
                        Execution Plan for <span className="text-user-hover">{goal.title}</span>
                    </h2>
                    <p className="text-base text-user-text/80 max-w-2xl">
                        Review the AI-generated high-level strategy and weekly focus before locking in this objective.
                    </p>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                    <div className="space-y-8">
                        <div>
                            <h4 className="text-sm font-semibold text-user-text mb-4 flex items-center gap-2">
                                <svg className="w-5 h-5 text-user-text/40" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                </svg>
                                Weekly Structure
                            </h4>
                            <div className="space-y-3">
                                {summary.weeklyStructure?.map((week, idx) => (
                                    <div key={idx} className="flex items-start gap-4 p-4 bg-user-bg/50 rounded-xl border border-user-sidebar">
                                        <div className="w-10 h-10 rounded-lg bg-user-card shadow-sm flex items-center justify-center text-sm font-semibold text-user-text border border-user-sidebar shrink-0">
                                            W{week.week}
                                        </div>
                                        <div className="pt-1">
                                            <p className="text-sm font-medium text-user-text">{week.focus}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <div>
                            <h4 className="text-sm font-semibold text-user-text mb-4 flex items-center gap-2">
                                <svg className="w-5 h-5 text-user-text/40" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                                </svg>
                                Focus Areas
                            </h4>
                            <div className="flex flex-wrap gap-2">
                                {summary.focusAreas?.map((area, idx) => (
                                    <span key={idx} className="px-3 py-1.5 bg-user-card border border-user-sidebar rounded-lg text-sm font-medium text-user-text/80 shadow-sm">
                                        {area}
                                    </span>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="space-y-8">
                        <div className="p-6 bg-user-bg/50 rounded-2xl text-user-text shadow-sm relative overflow-hidden">
                            <div className="relative z-10">
                                <h4 className="text-xs font-semibold text-user-text/60 uppercase tracking-wider mb-2">Master Strategy</h4>
                                <p className="text-base font-medium leading-relaxed mb-6 italic text-user-text/80">
                                    "{summary.strategy}"
                                </p>
                                <div className="h-px w-full bg-user-sidebar mb-6"></div>
                                <div className="flex items-center justify-between">
                                    <div>
                                        <p className="text-xs text-user-text/60 font-medium mb-1">Daily Investment</p>
                                        <p className="text-lg font-bold">{summary.dailyEffort}</p>
                                    </div>
                                    <div className="w-10 h-10 bg-user-sidebar rounded-lg flex items-center justify-center text-user-text/40">
                                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                                        </svg>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div>
                            <h4 className="text-sm font-semibold text-user-text mb-4 flex items-center gap-2">
                                <svg className="w-5 h-5 text-user-text/40" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                                </svg>
                                Skill Distribution
                            </h4>
                            <div className="space-y-4">
                                {summary.skillDistribution?.map((skill, idx) => (
                                    <div key={idx} className="space-y-1.5">
                                        <div className="flex justify-between text-xs font-medium text-user-text/80">
                                            <span>{skill.skill}</span>
                                            <span className="text-user-text">{skill.percentage}%</span>
                                        </div>
                                        <div className="h-2 w-full bg-user-sidebar rounded-full overflow-hidden">
                                            <div
                                                className="h-full bg-user-hover rounded-full transition-all duration-1000 ease-out"
                                                style={{ width: `${skill.percentage}%` }}
                                            ></div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>

                <div className="mt-10 pt-8 border-t border-user-sidebar flex flex-col items-center space-y-6">
                    {showRegenerateInput && (
                        <div className="w-full max-w-2xl space-y-4">
                            <div className="relative">
                                <textarea
                                    className="w-full rounded-xl border border-user-sidebar bg-user-card focus:border-user-hover focus:ring-1 focus:ring-user-hover p-4 text-sm font-medium text-user-text transition-all min-h-[120px]"
                                    placeholder="e.g. 'I want more focus on practical projects' or 'Give more weight to System Design'..."
                                    value={regeneratePrompt}
                                    onChange={(e) => setRegeneratePrompt(e.target.value)}
                                />
                                <div className="absolute bottom-4 right-4 flex space-x-2">
                                    <button
                                        onClick={() => setShowRegenerateInput(false)}
                                        className="px-4 py-2 text-sm font-medium text-user-text/60 hover:text-user-text transition-colors"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        onClick={handleRegenerate}
                                        disabled={loading}
                                        className="px-5 py-2 bg-user-card text-user-text border border-user-sidebar text-sm font-medium rounded-lg hover:bg-user-hover hover:text-gray-900 transition-colors disabled:opacity-50"
                                    >
                                        {loading ? "Regenerating..." : "Apply Feedback"}
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="flex flex-col sm:flex-row items-center gap-4 w-full justify-center">
                        <button
                            onClick={handleAccept}
                            disabled={loading}
                            className="bg-user-card hover:bg-user-hover text-user-text hover:text-gray-900 border border-user-sidebar py-3.5 px-8 rounded-xl font-medium text-base transition-colors shadow-sm disabled:opacity-50 w-full sm:w-auto"
                        >
                            {loading ? "Processing..." : "Accept & Start Roadmap"}
                        </button>

                        {!showRegenerateInput && (
                            <button
                                onClick={() => setShowRegenerateInput(true)}
                                disabled={loading}
                                className="bg-user-card hover:bg-user-hover text-user-text hover:text-gray-900 py-3.5 px-8 rounded-xl font-medium text-base border border-user-sidebar transition-colors disabled:opacity-50 w-full sm:w-auto"
                            >
                                Regenerate Plan
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SummaryPlanView;
