import API from "../services/api";

export const getAllUsers = (page = 1, limit = 50) => API.get(`/admin/users?page=${page}&limit=${limit}`);
export const blockUser = (id) => API.patch(`/admin/users/${id}/block`);
export const unblockUser = (id) => API.patch(`/admin/users/${id}/unblock`);
export const getAllGoals = (page = 1, limit = 50) => API.get(`/admin/goals?page=${page}&limit=${limit}`);
export const getAllDailyPlans = (page = 1, limit = 50) => API.get(`/admin/daily-plans?page=${page}&limit=${limit}`);
export const getAdminStats = () => API.get("/admin/stats");
