import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { Logo } from "./common/Logo";

const Navbar = ({ onDashboardAction, isTransparent }) => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  return (
    <nav className={`${isTransparent ? 'bg-transparent' : 'bg-[#FDFBF7]/80 backdrop-blur-xl border-b border-stone-100/50'} sticky top-0 z-50`}>
      <div className="max-w-7xl mx-auto px-6 md:px-10">
        <div className="flex justify-between h-20 items-center">
          <div className="flex items-center">
            <Link to="/" className="flex items-center space-x-3 group">
              <div className="w-10 h-10 bg-gradient-to-br from-primary to-secondary rounded-xl flex items-center justify-center shadow-lg shadow-brand-indigo/20 group-hover:scale-110 transition-transform duration-300">
                <Logo className="w-6 h-6 text-white" />
              </div>
              <span className={`text-2xl font-black ${isTransparent ? 'text-white' : 'text-primary'} tracking-tighter`}>
                PrepYou
              </span>
            </Link>
            {user?.role === "admin" && (
              <Link to="/admin-dashboard" className="ml-4 text-xs font-bold text-accent hover:text-primary transition-all px-2.5 py-1 bg-accent/10 rounded-lg border border-accent/20">
                Admin Panel
              </Link>
            )}
          </div>

          <div className="hidden md:flex md:items-center md:space-x-10">
            <Link to="/" className={`text-sm font-bold ${isTransparent ? 'text-white/80 hover:text-white' : 'text-text-muted hover:text-primary'} transition-all flex items-center gap-2`}>
              Home
            </Link>
            {user ? (
              <>
                <Link
                  to="/dashboard"
                  onClick={() => onDashboardAction && onDashboardAction()}
                  className={`text-sm font-bold ${isTransparent ? 'text-white/80 hover:text-white' : 'text-text-muted hover:text-primary'} transition-all`}
                >
                  Dashboard
                </Link>
                <div className="h-6 w-px bg-gray-100 hidden md:block"></div>
                <button
                  onClick={handleLogout}
                  className={`px-6 py-2.5 rounded-2xl text-sm font-bold transition-all border ${isTransparent ? 'text-white bg-white/10 hover:bg-white/20 border-white/20' : 'bg-gray-50 text-text-primary hover:bg-red-50 hover:text-red-600 border-gray-100'}`}
                >
                  Logout
                </button>
              </>
            ) : (
              <>
                <Link to="/login" className="text-sm font-bold text-text-muted hover:text-primary transition-all">
                  Sign In
                </Link>
                <Link
                  to="/register"
                  className="px-6 py-3 rounded-2xl bg-accent text-white text-sm font-extrabold hover:bg-opacity-90 hover:-translate-y-0.5 transition-all shadow-xl shadow-brand-coral/20"
                >
                  Get Started
                </Link>
              </>
            )}
          </div>

          <div className="md:hidden flex items-center">
            <button className={`p-2 rounded-xl border ${isTransparent ? 'text-white bg-white/10 border-white/20 hover:bg-white/20' : 'text-text-muted hover:text-primary bg-gray-50 border-gray-100'}`}>
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
