import React, { useEffect, useState } from "react";
import { createPortal } from "react-dom";

const UIModal = ({
    isOpen,
    onClose,
    title,
    message,
    type = "alert", // alert, confirm, prompt
    onConfirm,
    confirmText = "Confirm",
    cancelText = "Cancel",
    isLoading = false,
    inputPlaceholder = "",
    defaultValue = ""
}) => {
    const [inputValue, setInputValue] = useState(defaultValue);

    useEffect(() => {
        if (isOpen && type === "prompt") {
            setInputValue(defaultValue);
        }

        // Prevent body scroll when modal is open
        if (isOpen) {
            document.body.style.overflow = "hidden";
        } else {
            document.body.style.overflow = "unset";
        }

        return () => {
            document.body.style.overflow = "unset";
        };
    }, [isOpen, type, defaultValue]);

    if (!isOpen) return null;

    const handleConfirm = () => {
        if (type === "prompt") {
            onConfirm(inputValue);
        } else {
            onConfirm();
        }
    };

    return createPortal(
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
            <div
                className="absolute inset-0 bg-gray-900/40 backdrop-blur-sm transition-opacity"
                onClick={!isLoading ? onClose : undefined}
            />

            <div className="relative bg-user-bg rounded-[2rem] shadow-2xl shadow-teal-900/10 w-full max-w-md transform transition-all scale-100 border-2 border-user-text overflow-hidden">
                {/* Header - User Theme Color */}
                <div className="bg-user-text px-8 py-6">
                    <h3 className="text-xl font-bold text-user-bg tracking-tight">
                        {title || (type === "confirm" ? "Confirm Action" : type === "prompt" ? "Input Required" : "Notice")}
                    </h3>
                </div>

                {/* Body */}
                <div className="p-8 space-y-6">
                    {message && (
                        <p className="text-user-text font-serif text-lg leading-relaxed">
                            {message}
                        </p>
                    )}

                    {type === "prompt" && (
                        <div>
                            <textarea
                                value={inputValue}
                                onChange={(e) => setInputValue(e.target.value)}
                                placeholder={inputPlaceholder}
                                className="w-full px-4 py-3 rounded-xl bg-user-card border-2 border-user-text focus:border-user-text focus:ring-4 focus:ring-user-hover transition-all font-medium text-user-text placeholder:text-user-text/60 resize-none min-h-[100px]"
                                autoFocus
                            />
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-8 pb-8 flex items-center gap-4 justify-end">
                    {type !== "alert" && (
                        <button
                            onClick={onClose}
                            disabled={isLoading}
                            className="px-6 py-3 rounded-xl text-user-text font-bold hover:bg-user-hover transition-all text-sm uppercase tracking-wide disabled:opacity-50"
                        >
                            {cancelText}
                        </button>
                    )}

                    <button
                        onClick={handleConfirm}
                        disabled={isLoading || (type === "prompt" && !inputValue.trim())}
                        className={`px-8 py-3 rounded-xl text-user-bg font-bold shadow-lg shadow-teal-900/10 transition-all text-sm uppercase tracking-wide transform active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed ${type === "alert" ? "bg-user-text hover:bg-user-text/80 w-full" : "bg-user-text hover:bg-user-text/80"
                            }`}
                    >
                        {isLoading ? (
                            <div className="flex items-center gap-2">
                                <div className="w-4 h-4 border-2 border-user-bg/30 border-t-user-bg rounded-full animate-spin" />
                                <span>Processing...</span>
                            </div>
                        ) : (
                            confirmText || "OK"
                        )}
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
};

export default UIModal;
