import React, { useState, useEffect } from "react";
import { getProgressSummary } from "../../../api/progressApi";
import "./Views.css";

const ProgressView = ({ goal }) => {
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchProgress = async () => {
            try {
                const res = await getProgressSummary();
                setStats(res.data);
            } catch (err) {
                console.error("Failed to fetch progress", err);
            } finally {
                setLoading(false);
            }
        };
        fetchProgress();
    }, []);

    if (loading) return (
        <div className="flex flex-col items-center justify-center min-h-[40vh] space-y-4">
            <div className="w-10 h-10 border-4 border-gray-100 border-t-primary rounded-full animate-spin"></div>
            <p className="text-sm font-medium text-gray-500">Analyzing your growth trajectory...</p>
        </div>
    );

    if (!stats) return (
        <div className="max-w-4xl mx-auto py-20 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="bg-user-card p-12 rounded-2xl shadow-sm border border-user-sidebar flex flex-col items-center text-center space-y-6">
                <div className="w-16 h-16 bg-user-bg/50 text-user-text/40 rounded-full flex items-center justify-center shadow-inner ring-8 ring-user-bg/50">
                    <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                    </svg>
                </div>
                <div className="space-y-2">
                    <h2 className="text-2xl font-bold text-user-text">No Data Points Yet</h2>
                    <p className="text-sm font-medium text-user-text/80 max-w-sm">Complete your first task to unlock deep analytics.</p>
                </div>
            </div>
        </div>
    );

    const { today, weekly, trend, levelSuggestion } = stats;

    return (
        <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 bg-user-card p-6 rounded-2xl shadow-sm border border-user-sidebar">
                <div>
                    <h2 className="text-2xl font-bold text-user-text">Your Progress Journey</h2>
                    <p className="text-sm font-medium text-user-text/80 mt-1">
                        Real-time quantification of your learning momentum.
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Today's Snapshot */}
                <div className="bg-user-card p-8 rounded-2xl shadow-sm border border-user-sidebar flex flex-col justify-between relative overflow-hidden">
                    <div className="relative z-10">
                        <h3 className="text-base font-semibold text-user-text mb-6 flex items-center gap-2">
                            <svg className="w-5 h-5 text-user-text/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                            Today's Pulse
                        </h3>
                        <div className="flex flex-col sm:flex-row items-center gap-8">
                            <div className="relative w-40 h-40 flex items-center justify-center">
                                <svg className="w-full h-full transform -rotate-90">
                                    <circle className="text-gray-100" strokeWidth="10" stroke="currentColor" fill="transparent" r="70" cx="80" cy="80" />
                                    <circle
                                        className="text-primary transition-all duration-1000 ease-out"
                                        strokeWidth="10"
                                        strokeDasharray={440}
                                        strokeDashoffset={440 - (440 * today.completionPercentage) / 100}
                                        strokeLinecap="round"
                                        stroke="currentColor"
                                        fill="transparent"
                                        r="70"
                                        cx="80"
                                        cy="80"
                                    />
                                </svg>
                                <div className="absolute flex flex-col items-center">
                                    <span className="text-3xl font-bold text-user-text">{today.completionPercentage}%</span>
                                    <span className="text-xs font-semibold text-user-text/80 uppercase tracking-wider mt-1">Velocity</span>
                                </div>
                            </div>
                            <div className="flex-1 w-full space-y-3">
                                {[
                                    { label: "Execution", val: today.completedTasks, color: "text-green-600", bg: "bg-green-50", icon: "M5 13l4 4L19 7" },
                                    { label: "Active", val: today.pendingTasks, color: "text-amber-600", bg: "bg-amber-50", icon: "M13 10V3L4 14h7v7l9-11h-7z" },
                                    { label: "Deferred", val: today.rolledOverTasks, color: "text-blue-600", bg: "bg-blue-50", icon: "M13 5l7 7-7 7M5 5l7 7-7 7" }
                                ].map((s) => (
                                    <div key={s.label} className="flex items-center justify-between p-3 bg-user-card rounded-xl border border-user-sidebar shadow-sm">
                                        <div className="flex items-center space-x-3">
                                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${s.bg} ${s.color}`}>
                                                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={s.icon} />
                                                </svg>
                                            </div>
                                            <span className="text-sm font-medium text-user-text">{s.label}</span>
                                        </div>
                                        <span className="text-base font-bold text-user-text">{s.val}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Last 7 Days Trend (Graph) */}
                <div className="bg-user-card p-8 rounded-2xl shadow-sm border border-user-sidebar relative overflow-hidden">
                    <div className="relative z-10 flex flex-col h-full">
                        <div className="mb-6 flex items-center gap-2 text-user-text">
                            <svg className="w-5 h-5 text-user-text/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z" />
                            </svg>
                            <div>
                                <h3 className="text-base font-semibold">Weekly Progress</h3>
                                <p className="text-xs font-medium text-user-text/80 mt-0.5">Behavioral Consistency Graph</p>
                            </div>
                        </div>

                        <div className="flex-1 flex items-end justify-between relative pl-8 pt-4 min-h-[160px]">
                            {/* Y-Axis Labels */}
                            <div className="absolute left-0 top-0 bottom-6 flex flex-col justify-between text-xs font-medium text-user-text/60">
                                <span>100%</span>
                                <span>50%</span>
                                <span>0%</span>
                            </div>

                            {/* Grid Lines */}
                            <div className="absolute left-8 right-0 top-0 bottom-6 flex flex-col justify-between z-0">
                                <div className="w-full h-px bg-user-sidebar border-t border-dashed border-user-sidebar"></div>
                                <div className="w-full h-px bg-user-sidebar border-t border-dashed border-user-sidebar"></div>
                                <div className="w-full h-px bg-user-sidebar border-t border-dashed border-user-sidebar"></div>
                            </div>

                            {/* SVG Chart */}
                            <svg className="absolute left-8 right-0 top-0 bottom-6 w-full h-full overflow-visible z-10" viewBox="0 0 100 100" preserveAspectRatio="none">
                                <defs>
                                    <linearGradient id="gradientDetails" x1="0" x2="0" y1="0" y2="1">
                                        <stop offset="0%" stopColor="#4F46E5" stopOpacity="0.2" />
                                        <stop offset="100%" stopColor="#4F46E5" stopOpacity="0" />
                                    </linearGradient>
                                </defs>
                                <path
                                    d={`M0,100 ${trend.map((d, i) => `L${(i / (trend.length - 1 || 1)) * 100},${100 - d.percentage}`).join(' ')} L100,100 Z`}
                                    fill="url(#gradientDetails)"
                                />
                                <polyline
                                    fill="none"
                                    stroke="#4F46E5"
                                    strokeWidth="2"
                                    vectorEffect="non-scaling-stroke"
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    points={
                                        trend.length > 0
                                            ? trend.map((d, i) => `${(i / (trend.length - 1 || 1)) * 100},${100 - d.percentage}`).join(' ')
                                            : "0,100 100,100"
                                    }
                                />
                                {trend.map((d, i) => (
                                    <circle
                                        key={i}
                                        cx={(i / (trend.length - 1 || 1)) * 100}
                                        cy={100 - d.percentage}
                                        r="3"
                                        fill="#fff"
                                        stroke="#4F46E5"
                                        strokeWidth="2"
                                        vectorEffect="non-scaling-stroke"
                                        className="hover:r-4 transition-all duration-300 origin-center cursor-pointer shadow-sm"
                                    />
                                ))}
                            </svg>

                            {/* X-Axis Labels */}
                            <div className="w-full flex justify-between absolute bottom-0 left-8 right-0 translate-y-full pt-3">
                                {trend.map((day, i) => (
                                    <div key={i} className="text-xs font-medium text-user-text/80 uppercase text-center w-8">
                                        {new Date(day.date).toLocaleDateString([], { weekday: 'short' }).charAt(0)}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Weekly Summary */}
            <div className="bg-user-card p-8 md:p-10 rounded-2xl shadow-sm border border-user-sidebar">
                <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
                    {[
                        { label: "Avg. Completion", val: `${weekly.averageCompletion}%`, sub: "Weekly Velocity", color: "text-user-text" },
                        { label: "Total Directives", val: weekly.totalTasks, sub: "Total Assignments", color: "text-user-text" },
                        { label: "Successful Sorties", val: weekly.completedTasks, sub: "Mission Completion", color: "text-green-600" },
                        { label: "Bypassed Targets", val: weekly.rolledOverTasks, sub: "Roll-over Count", color: weekly.rolledOverTasks > 5 ? "text-red-600" : "text-user-text" }
                    ].map((item) => (
                        <div key={item.label} className="text-center md:text-left space-y-1">
                            <p className="text-xs font-semibold text-user-text/80 uppercase tracking-wide">{item.label}</p>
                            <p className={`text-3xl font-bold ${item.color}`}>{item.val}</p>
                            <p className="text-xs font-medium text-user-text/60">{item.sub}</p>
                        </div>
                    ))}
                </div>

                {/* Weekly Reflection Insights (New) */}
                {stats.weeklyReflections && (
                    <div className="mt-8 pt-8 border-t border-user-sidebar grid grid-cols-1 md:grid-cols-2 gap-8">
                        <div className="flex items-center gap-5 p-4 bg-user-bg/50 rounded-xl border border-user-sidebar">
                            <div className="w-12 h-12 bg-user-card rounded-lg flex items-center justify-center text-blue-600 shadow-sm border border-user-sidebar">
                                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                                </svg>
                            </div>
                            <div>
                                <p className="text-xs font-semibold text-user-text/80 uppercase tracking-wide">Journals Written</p>
                                <p className="text-2xl font-bold text-user-text">{stats.weeklyReflections.totalJournals}</p>
                                <p className="text-xs font-medium text-user-text/60 mt-0.5">Self-Reflections</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-5 p-4 bg-user-bg/50 rounded-xl border border-user-sidebar">
                            <div className="w-12 h-12 bg-user-card rounded-lg flex items-center justify-center text-pink-500 shadow-sm border border-user-sidebar">
                                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                                </svg>
                            </div>
                            <div>
                                <p className="text-xs font-semibold text-user-text/80 uppercase tracking-wide">Dominant Mood</p>
                                <p className="text-2xl font-bold text-user-text capitalize">{stats.weeklyReflections.mostFrequentMood || "N/A"}</p>
                                <p className="text-xs font-medium text-user-text/60 mt-0.5">Emotional Baseline</p>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* AI Insights */}
            <div className="bg-gray-900 p-8 md:p-10 rounded-2xl text-white shadow-sm relative overflow-hidden">
                <div className="relative z-10 flex flex-col md:flex-row items-center gap-8">
                    <div className="w-16 h-16 bg-gray-800 rounded-xl flex items-center justify-center text-primary border border-gray-700">
                        <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                        </svg>
                    </div>
                    <div className="flex-1 text-center md:text-left space-y-3">
                        <span className="inline-block px-3 py-1 bg-gray-800 rounded-md text-xs font-semibold uppercase tracking-wider text-gray-300">AI Strategic Insight</span>
                        <div className="text-xl md:text-2xl font-semibold leading-tight text-white">
                            {weekly.averageCompletion > 70 ? (
                                <p>Operational efficiency is peak. Consistency exceeds 70%. <span className="text-primary">{levelSuggestion === 'upgrade' ? "Ready for Level Tier Up." : "Maintain current momentum."}</span></p>
                            ) : weekly.averageCompletion > 40 ? (
                                <p>Moderate progress detected. <span className="text-amber-400">Action: Reduce task overflow to optimize retention.</span></p>
                            ) : (
                                <p>Efficiency drop-off detected. <span className="text-red-400">{levelSuggestion === 'downgrade' ? "Recommendation: Recalibrate goal intensity." : "Prioritize High-Impact tasks."}</span></p>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProgressView;
