import React, { useState } from "react";
import GoalForm from "../GoalForm";
import UIModal from "../../common/UIModal";
import { deleteGoal } from "../../../api/goalApi";
import "./Views.css";

const GoalSetupView = ({ goal, onGoalCreated, setView }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [modal, setModal] = useState({ isOpen: false, type: "confirm", title: "", message: "", onConfirm: () => { } });

    const handleEditSuccess = () => {
        setIsEditing(false);
        onGoalCreated();
    };

    const closeModal = () => setModal(prev => ({ ...prev, isOpen: false }));

    const handleReset = async () => {
        try {
            await deleteGoal(goal._id);
            setModal({
                isOpen: true,
                type: "alert",
                title: "Goal Reset",
                message: "Your goal has been successfully deleted.",
                onConfirm: () => {
                    closeModal();
                    onGoalCreated(); // Refresh parent data (will result in no active goal)
                }
            });
        } catch (error) {
            setModal({
                isOpen: true,
                type: "alert",
                title: "Error",
                message: "Failed to reset goal: " + (error.response?.data?.message || error.message),
                onConfirm: closeModal
            });
        }
    };

    const confirmReset = () => {
        setModal({
            isOpen: true,
            type: "confirm",
            title: "Reset Goal?",
            message: "Are you sure you want to reset your goal? This will delete all progress and cannot be undone.",
            confirmText: "Yes, Reset Everything",
            onConfirm: handleReset
        });
    };

    return (
        <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <UIModal
                isOpen={modal.isOpen}
                onClose={closeModal}
                {...modal}
            />
            {!goal || isEditing ? (
                <div className="flex flex-col items-center text-center space-y-8">
                    {!goal && (
                        <div className="p-4 bg-user-bg/50 rounded-2xl border border-user-sidebar">
                            <div className="w-20 h-20 bg-user-card rounded-xl flex items-center justify-center text-blue-600 shadow-sm border border-user-sidebar">
                                <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                                </svg>
                            </div>
                        </div>
                    )}
                    <GoalForm
                        onSuccess={handleEditSuccess}
                        initialData={goal}
                        onCancel={isEditing ? () => setIsEditing(false) : null}
                    />
                </div>
            ) : (
                <div className="bg-user-card p-8 md:p-10 rounded-2xl shadow-sm border border-user-sidebar">
                    <div className="flex flex-col md:flex-row md:items-start justify-between gap-6 mb-8 pb-8 border-b border-user-sidebar/50">
                        <div className="space-y-2 max-w-xl">
                            <h2 className="text-3xl font-bold text-user-text leading-tight">
                                {goal.title}
                            </h2>
                        </div>
                        <div className="flex flex-col items-end gap-3 shrink-0">
                            {goal.status === "draft" && (
                                <button
                                    onClick={() => setView("dashboard")}
                                    className="px-6 py-2.5 bg-user-text text-user-card hover:bg-user-hover hover:text-gray-900 rounded-xl text-sm font-semibold transition-colors shadow-sm"
                                >
                                    View AI Roadmap
                                </button>
                            )}
                            <div className="flex space-x-3">
                                <button
                                    onClick={() => setIsEditing(true)}
                                    className="px-5 py-2 bg-user-card text-user-text hover:bg-user-hover rounded-lg text-sm font-medium transition-colors border border-user-sidebar shadow-sm"
                                >
                                    Edit Goal
                                </button>
                                <button
                                    onClick={confirmReset}
                                    className="px-5 py-2 bg-user-modal text-user-text hover:bg-user-hover hover:text-gray-900 rounded-lg text-sm font-medium transition-colors border border-user-sidebar"
                                >
                                    Reset
                                </button>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                        <div className="p-6 bg-user-bg/50 rounded-xl border border-user-sidebar/50">
                            <p className="text-xs font-semibold text-user-text/80 uppercase tracking-widest mb-3">Target Level</p>
                            <div className="flex items-center gap-3 text-xl font-bold text-user-text">
                                <svg className="w-6 h-6 text-user-text/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
                                </svg>
                                <span>{goal.level}</span>
                            </div>
                        </div>
                        <div className="p-6 bg-user-bg/50 rounded-xl border border-user-sidebar/50">
                            <p className="text-xs font-semibold text-user-text/80 uppercase tracking-widest mb-3">Target Deadline</p>
                            <div className="flex items-center gap-3 text-xl font-bold text-user-text">
                                <svg className="w-6 h-6 text-user-text/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                                </svg>
                                <span>{new Date(goal.deadline).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' })}</span>
                            </div>
                        </div>
                    </div>

                    <div className="p-6 bg-user-bg/40 rounded-xl border border-user-sidebar/50">
                        <p className="text-xs font-semibold text-user-text uppercase tracking-widest mb-3">Strategic Description</p>
                        <p className="text-base font-medium text-user-text/90 leading-relaxed">
                            {goal.description || `Preparing for ${goal.target || 'your target'} with a focus on ${goal.level} level mastery.`}
                        </p>
                    </div>

                    <div className="mt-8 flex items-center justify-center p-4 bg-user-hover/30 rounded-xl border border-user-sidebar/50">
                        <p className="text-sm font-medium text-user-text text-center leading-relaxed flex items-center gap-2">
                            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                            {goal.status === "draft"
                                ? "Your roadmap is ready for review. Click 'View AI Roadmap' to start your mission."
                                : "To pivot your path, you'll need to archive current progress and re-architect your roadmap."
                            }
                        </p>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GoalSetupView;
