import React, { useEffect, useState, useCallback } from "react";
import "./AdminDashboard.css";
import { getAllUsers, getAllGoals, getAdminStats, blockUser, unblockUser, getAllDailyPlans } from "../api/adminApi";
import Navbar from "../components/Navbar";
import { motion, AnimatePresence } from "framer-motion";
import {
    FiUsers,
    FiTarget,
    FiActivity,
    FiBarChart2,
    FiShield,
    FiShieldOff,
    FiUser,
    FiCheckCircle,
    FiClock,
    FiList,
    FiTrendingUp,
    FiDollarSign,
    FiStar
} from "react-icons/fi";
import { toast } from "react-hot-toast";

const AdminDashboard = () => {
    const [activeTab, setActiveTab] = useState("overview");
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);
    const [users, setUsers] = useState([]);
    const [goals, setGoals] = useState([]);
    const [plans, setPlans] = useState([]);
    const [selectedDetail, setSelectedDetail] = useState(null);
    const [stats, setStats] = useState({
        totalUsers: 0,
        activeUsers: 0,
        totalGoals: 0,
        activeGoals: 0,
        completedGoals: 0,
        activeGoals: 0,
        completedGoals: 0,
        averageCompletionRate: 0,
        mostPopularGoalType: "N/A",
        revenue: 0,
        freeUsers: 0,
        proUsers: 0,
        positiveSentiment: 0,
        negativeSentiment: 0,
        totalJournals: 0
    });
    const [loading, setLoading] = useState(true);

    const fetchData = useCallback(async () => {
        try {
            setLoading(true);
            const [usersRes, goalsRes, statsRes, plansRes] = await Promise.all([
                getAllUsers(),
                getAllGoals(),
                getAdminStats(),
                getAllDailyPlans(),
            ]);

            setUsers(usersRes.data.users || usersRes.data);
            setGoals(goalsRes.data.goals || goalsRes.data);
            setStats(statsRes.data);
            setPlans(plansRes.data.plans || plansRes.data);
        } catch (error) {
            console.error("Failed to fetch admin data", error);
            toast.error(error.response?.data?.message || "Failed to load admin data");
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleSidebarClick = (tab) => {
        setActiveTab(tab);
        if (window.innerWidth < 768) setIsSidebarOpen(false);
        fetchData();
    };

    const handleBlockToggle = async (user) => {
        try {
            if (user.isBlocked) {
                await unblockUser(user._id);
                toast.success(`${user.name} unblocked`);
            } else {
                await blockUser(user._id);
                toast.success(`${user.name} blocked`);
            }
            // Update local state for immediate feedback
            setUsers(prev => prev.map(u =>
                u._id === user._id ? { ...u, isBlocked: !u.isBlocked } : u
            ));
            // Refresh stats in background
            const statsRes = await getAdminStats();
            setStats(statsRes.data);
        } catch (error) {
            toast.error(error.response?.data?.message || "Action failed");
        }
    };

    const handleStatClick = useCallback((type) => {
        switch (type) {
            case 'users':
                setActiveTab('users');
                document.querySelector('.admin-content-section')?.scrollIntoView({ behavior: 'smooth' });
                break;
            case 'goals':
                setActiveTab('goals');
                document.querySelector('.admin-content-section')?.scrollIntoView({ behavior: 'smooth' });
                break;
            case 'plans':
                setActiveTab('plans');
                document.querySelector('.admin-content-section')?.scrollIntoView({ behavior: 'smooth' });
                break;
            case 'completion':
                setSelectedDetail({
                    title: "System Performance",
                    icon: <FiTrendingUp />,
                    color: "indigo",
                    content: (
                        <div className="space-y-4">
                            <div className="bg-indigo-50 p-4 rounded-xl border border-indigo-100">
                                <p className="text-sm font-semibold text-indigo-600 uppercase tracking-wider mb-1">Average Completion Rate</p>
                                <p className="text-3xl font-bold text-[#8A244B]">{stats.averageCompletionRate}%</p>
                                <p className="text-xs text-indigo-500 mt-2">Across all daily plans submitted.</p>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                                    <p className="text-xs text-gray-500 uppercase font-semibold">Active Users</p>
                                    <p className="text-xl font-bold text-[#8A244B] mt-1">{stats.activeUsers}</p>
                                </div>
                                <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                                    <p className="text-xs text-gray-500 uppercase font-semibold">Total Goals</p>
                                    <p className="text-xl font-bold text-[#8A244B] mt-1">{stats.totalGoals}</p>
                                </div>
                            </div>
                        </div>
                    )
                });
                break;
            case 'revenue':
                setSelectedDetail({
                    title: "Revenue Analytics",
                    icon: <FiDollarSign />,
                    color: "emerald",
                    content: (
                        <div className="space-y-4">
                            <div className="bg-[#FB9B8F]/20 p-6 rounded-xl border border-[#FB9B8F]/30 text-center">
                                <p className="text-sm font-semibold text-[#8A244B] uppercase tracking-wider mb-1">Total Revenue</p>
                                <p className="text-4xl font-bold text-[#8A244B]">₹{stats.revenue || 0}</p>
                            </div>
                            <div className="space-y-2">
                                <button
                                    onClick={() => { setSelectedDetail(null); handleSidebarClick('users'); }}
                                    className="w-full flex justify-between items-center p-3 bg-white/70 rounded-lg shadow-sm border border-gray-100 hover:bg-white transition-colors"
                                >
                                    <span className="text-[#8A244B] flex items-center gap-2 font-medium"><FiStar className="text-yellow-500" /> Pro Users Details</span>
                                    <span className="font-bold text-[#8A244B]">{stats.proUsers || 0}</span>
                                </button>
                                <button
                                    onClick={() => { setSelectedDetail(null); handleSidebarClick('users'); }}
                                    className="w-full flex justify-between items-center p-3 bg-white/70 rounded-lg shadow-sm border border-gray-100 hover:bg-white transition-colors"
                                >
                                    <span className="text-[#8A244B] flex items-center gap-2 font-medium"><FiUser className="text-[#8A244B]" /> Free Users Details</span>
                                    <span className="font-bold text-[#8A244B]">{stats.freeUsers || 0}</span>
                                </button>
                            </div>
                        </div>
                    )
                });
                break;
            case 'conversion':
                const conversionRate = stats.totalUsers > 0 ? ((stats.proUsers / stats.totalUsers) * 100).toFixed(1) : 0;
                setSelectedDetail({
                    title: "Conversion Metrics",
                    icon: <FiStar />,
                    color: "yellow",
                    content: (
                        <div className="space-y-4">
                            <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-100">
                                <div className="flex justify-between items-end">
                                    <div>
                                        <p className="text-sm font-semibold text-yellow-600 uppercase tracking-wider mb-1">Pro Conversion Rate</p>
                                        <p className="text-3xl font-bold text-[#8A244B]">{conversionRate}%</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-xs text-yellow-600 font-medium">Target: 20%</p>
                                    </div>
                                </div>
                                <div className="w-full bg-yellow-200/50 h-2 rounded-full mt-4 overflow-hidden">
                                    <div className="bg-yellow-500 h-full rounded-full" style={{ width: `${Math.min(conversionRate, 100)}%` }}></div>
                                </div>
                            </div>
                            <p className="text-sm text-gray-500 font-medium leading-relaxed text-center">
                                {stats.proUsers} out of {stats.totalUsers} registered users have upgraded to Pro.
                            </p>
                        </div>
                    )
                });
                break;
            default:
                break;
        }
    }, [stats]);

    if (loading && stats.totalUsers === 0) {
        return (
            <div className="admin-loading">
                <div className="loader"></div>
                <p>Establishing Secure Admin Connection...</p>
            </div>
        );
    }

    return (
        <div className="admin-page-container flex flex-col min-h-screen relative">
            <Navbar />
            <div className="flex flex-1 relative w-full items-stretch justify-start">
                <AdminSidebar activeTab={activeTab} onTabSelect={handleSidebarClick} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />

                <main className={`admin-main flex-1 transition-all duration-300 ${isSidebarOpen ? 'md:ml-64' : 'md:ml-20'} ml-20 w-full h-full pb-20`}>
                    <header className="admin-header-section flex flex-col md:flex-row md:items-end md:justify-between mb-8 pb-4 border-b border-[var(--border-color)]">
                        <div className="header-text">
                            <motion.h1
                                initial={{ opacity: 0, y: -20 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="text-3xl font-bold text-[var(--text-primary)] mb-2"
                            >
                                Admin Dashboard
                            </motion.h1>
                            <p className="text-[var(--text-secondary)]">A unified perspective on platform analytics and user engagement.</p>
                        </div>
                    </header>

                    <AnimatePresence mode="wait">
                        {activeTab === 'overview' && (
                            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} key="overview">
                                <div className="stats-grid">
                                    <StatCard icon={<FiUsers />} label="Total Users" value={stats.totalUsers} color="indigo" subtext={`${stats.activeUsers} Active (7d)`} onClick={() => handleStatClick('users')} delay={0.1} />
                                    <StatCard icon={<FiTarget />} label="Active Goals" value={stats.activeGoals} color="purple" subtext={`Popular: ${stats.mostPopularGoalType}`} onClick={() => handleStatClick('goals')} delay={0.2} />
                                    <StatCard icon={<FiDollarSign />} label="Total Revenue" value={`₹${stats.revenue || 0}`} color="green" subtext={`${stats.proUsers || 0} Pro Users`} onClick={() => handleStatClick('revenue')} delay={0.3} />
                                </div>

                                <div className="mt-8 bg-white/60 p-6 rounded-2xl border border-gray-100 shadow-sm">
                                    <div className="flex justify-between items-center mb-6">
                                        <div>
                                            <h3 className="text-xl font-bold text-[#8A244B]">Insights: Sentiment Trends</h3>
                                            <p className="text-sm text-[#8A244B]/70 mt-1">Derived from user journal entries to understand engagement and motivation levels.</p>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-4">
                                        <div className="bg-[#FFF7CD]/50 p-6 rounded-xl border border-[#FDC3A1]/50 flex flex-col items-center justify-center">
                                            <p className="text-sm font-semibold text-[#8A244B] uppercase tracking-wider mb-2">Total Journal Entries</p>
                                            <p className="text-5xl font-bold text-[#8A244B]">{stats.totalJournals}</p>
                                        </div>

                                        <div className="bg-[#FFF7CD]/50 p-6 rounded-xl border border-[#FDC3A1]/50">
                                            <p className="text-sm font-semibold text-[#8A244B] uppercase tracking-wider mb-4 border-b border-[#FDC3A1] pb-2">Sentiment Breakdown</p>

                                            <div className="space-y-4">
                                                <div>
                                                    <div className="flex justify-between text-sm font-medium mb-1">
                                                        <span className="text-[#8A244B]">Positive</span>
                                                        <span className="text-[#8A244B]">{stats.totalJournals > 0 ? Math.round((stats.positiveSentiment / stats.totalJournals) * 100) : 0}%</span>
                                                    </div>
                                                    <div className="w-full bg-white h-2.5 rounded-full overflow-hidden border border-[#FDC3A1]/30 block">
                                                        <div className="bg-[#7AAACE] h-full rounded-full transition-all duration-1000" style={{ width: `${stats.totalJournals > 0 ? (stats.positiveSentiment / stats.totalJournals) * 100 : 0}%` }}></div>
                                                    </div>
                                                </div>

                                                <div>
                                                    <div className="flex justify-between text-sm font-medium mb-1 mt-2">
                                                        <span className="text-[#8A244B]">Negative</span>
                                                        <span className="text-[#8A244B]">{stats.totalJournals > 0 ? Math.round((stats.negativeSentiment / stats.totalJournals) * 100) : 0}%</span>
                                                    </div>
                                                    <div className="w-full bg-white h-2.5 rounded-full overflow-hidden border border-[#FDC3A1]/30 block">
                                                        <div className="bg-[#FB9B8F] h-full rounded-full transition-all duration-1000" style={{ width: `${stats.totalJournals > 0 ? (stats.negativeSentiment / stats.totalJournals) * 100 : 0}%` }}></div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="mt-8 bg-white/60 p-6 rounded-2xl border border-gray-100 shadow-sm">
                                    <div className="flex justify-between items-center mb-6">
                                        <div>
                                            <h3 className="text-xl font-bold text-[#8A244B]">Platform Productivity Metrics</h3>
                                            <p className="text-sm text-[#8A244B]/70 mt-1">Real-time health analysis comparing active engagement against total platform data.</p>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                        <div className="bg-[#FB9B8F]/10 p-5 rounded-xl border border-[#FB9B8F]/30 relative overflow-hidden">
                                            <p className="text-xs font-bold text-[#8A244B] uppercase tracking-wider mb-2">User Engagement</p>
                                            <div className="flex items-end gap-2 mb-2">
                                                <span className="text-4xl font-bold text-[#8A244B]">{stats.totalUsers > 0 ? Math.round((stats.activeUsers / stats.totalUsers) * 100) : 0}%</span>
                                            </div>
                                            <p className="text-xs font-medium text-[#8A244B]/70">{stats.activeUsers} out of {stats.totalUsers} users active this week</p>
                                            <FiUsers className="absolute -bottom-4 -right-2 text-6xl text-[#FB9B8F]/20" />
                                        </div>

                                        <div className="bg-[#7AAACE]/10 p-5 rounded-xl border border-[#7AAACE]/30 relative overflow-hidden">
                                            <p className="text-xs font-bold text-[#8A244B] uppercase tracking-wider mb-2">Active Goal Ratio</p>
                                            <div className="flex items-end gap-2 mb-2">
                                                <span className="text-4xl font-bold text-[#8A244B]">{stats.totalGoals > 0 ? Math.round((stats.activeGoals / stats.totalGoals) * 100) : 0}%</span>
                                            </div>
                                            <p className="text-xs font-medium text-[#8A244B]/70">{stats.activeGoals} currently ongoing out of {stats.totalGoals} total</p>
                                            <FiTarget className="absolute -bottom-4 -right-2 text-6xl text-[#7AAACE]/20" />
                                        </div>

                                        <div className="bg-[#FDC3A1]/20 p-5 rounded-xl border border-[#FDC3A1]/50 relative overflow-hidden">
                                            <p className="text-xs font-bold text-[#8A244B] uppercase tracking-wider mb-2">Execution Health</p>
                                            <div className="flex items-end gap-2 mb-2">
                                                <span className="text-4xl font-bold text-[#8A244B]">{stats.averageCompletionRate}%</span>
                                            </div>
                                            <p className="text-xs font-medium text-[#8A244B]/70">Average completion rate across all study plans</p>
                                            <FiCheckCircle className="absolute -bottom-4 -right-2 text-6xl text-[#FDC3A1]/40" />
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        )}

                        {activeTab === 'analytics' && (
                            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} key="analytics">
                                <div className="stats-grid">
                                    <StatCard icon={<FiTrendingUp />} label="Completion Rate" value={`${stats.averageCompletionRate}%`} color="cyan" subtext="System-wide average" onClick={() => handleStatClick('completion')} delay={0.1} />
                                    <StatCard icon={<FiList />} label="Recent Plans" value={plans.length} color="emerald" subtext="Daily study plans tracked" onClick={() => handleStatClick('plans')} delay={0.2} />
                                    <StatCard icon={<FiStar />} label="Pro Conversion" value={`${stats.totalUsers > 0 ? ((stats.proUsers / stats.totalUsers) * 100).toFixed(1) : 0}%`} color="yellow" subtext={`${stats.freeUsers || 0} Free Users`} onClick={() => handleStatClick('conversion')} delay={0.3} />
                                </div>
                            </motion.div>
                        )}

                        {(activeTab === 'users' || activeTab === 'goals' || activeTab === 'plans') && (
                            <div className="admin-content-section w-full mt-4">
                                <div className="table-container shadow-xl">
                                    {activeTab === "users" && <UserTable key="users" users={users} onBlockToggle={handleBlockToggle} />}
                                    {activeTab === "goals" && <GoalTable key="goals" goals={goals} />}
                                    {activeTab === "plans" && <GroupedActivity key="plans" plans={plans} />}
                                </div>
                            </div>
                        )}
                    </AnimatePresence>
                </main>
            </div>

            {/* Detail Modal */}
            <AnimatePresence>
                {selectedDetail && (
                    <StatDetailModal
                        detail={selectedDetail}
                        onClose={() => setSelectedDetail(null)}
                    />
                )}
            </AnimatePresence>
        </div>
    );
};

const StatCard = React.memo(({ icon, label, value, color, subtext, onClick, delay = 0 }) => (
    <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay, duration: 0.3 }}
        whileHover={{ y: -5, scale: 1.02 }}
        whileTap={{ scale: 0.95 }}
        className={`stat-card card-${color} cursor-pointer hover:shadow-lg transition-shadow relative overflow-hidden group`}
        onClick={onClick}
    >
        <div className="card-icon shadow-inner">{icon}</div>
        <div className="card-info z-10">
            <span className="stat-label">{label}</span>
            <span className="stat-value">{value}</span>
            <span className="stat-subtext font-medium">{subtext}</span>
        </div>
        <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
            <div className="bg-white/10 p-1.5 rounded-lg text-xs text-white/70">
                View
            </div>
        </div>
    </motion.div>
));

const TabButton = React.memo(({ active, onClick, icon, label }) => (
    <button className={`tab-btn ${active ? 'active' : ''}`} onClick={onClick}>
        {icon}
        <span>{label}</span>
    </button>
));

const UserTable = React.memo(({ users, onBlockToggle }) => (
    <motion.div
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: -20 }}
    >
        <table className="premium-table">
            <thead>
                <tr>
                    <th>User</th>
                    <th>Role</th>
                    <th>Status</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                {users.map((user) => (
                    <tr key={user._id}>
                        <td>
                            <div className="user-info-cell">
                                <div className="avatar">
                                    <FiUser />
                                </div>
                                <div className="details">
                                    <span className="name">{user.name}</span>
                                    <span className="email">{user.email}</span>
                                </div>
                            </div>
                        </td>
                        <td>
                            <span className={`role-badge ${user.role}`}>
                                {user.role}
                            </span>
                        </td>
                        <td>
                            <span className={`status-pill ${user.isBlocked ? 'blocked' : 'active'}`}>
                                {user.isBlocked ? 'Blocked' : 'Active'}
                            </span>
                        </td>
                        <td>
                            <div className="active-time">
                                <FiClock />
                                <span>{user.lastActiveAt ? new Date(user.lastActiveAt).toLocaleString() : "Never"}</span>
                            </div>
                        </td>
                        <td>
                            {user.role !== 'admin' && (
                                <button
                                    className={`action-btn ${user.isBlocked ? 'unblock' : 'block'}`}
                                    onClick={() => onBlockToggle(user)}
                                >
                                    {user.isBlocked ? <FiShield /> : <FiShieldOff />}
                                    <span>{user.isBlocked ? 'Unblock' : 'Block'}</span>
                                </button>
                            )}
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
        {users.length === 0 && <div className="empty-state">No users found in system.</div>}
    </motion.div>
));

const GoalTable = React.memo(({ goals }) => (
    <motion.div
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: -20 }}
    >
        <table className="premium-table">
            <thead>
                <tr>
                    <th>User</th>
                    <th>Goal Title</th>
                    <th>Type</th>
                    <th>Level</th>
                    <th>Status</th>
                </tr>
            </thead>
            <tbody>
                {goals.map((goal) => (
                    <tr key={goal._id}>
                        <td>
                            <div className="details">
                                <span className="name">{goal.user?.name || "Unknown"}</span>
                                <span className="email">{goal.user?.email || ""}</span>
                            </div>
                        </td>
                        <td>{goal.title}</td>
                        <td className="capitalize">{goal.preparationMode}</td>
                        <td>
                            <span className={`level-badge ${goal.level?.toLowerCase()}`}>
                                {goal.level}
                            </span>
                        </td>
                        <td>
                            <span className={`status-pill ${goal.status === 'accepted' ? 'active' : ''}`}>
                                {goal.status}
                            </span>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
        {goals.length === 0 && <div className="empty-state">No goals to track.</div>}
    </motion.div>
));

const PlanTable = React.memo(({ plans }) => (
    <motion.div
        initial={{ opacity: 0, x: 20 }}
        animate={{ opacity: 1, x: 0 }}
        exit={{ opacity: 0, x: -20 }}
    >
        <table className="premium-table">
            <thead>
                <tr>
                    <th>User</th>
                    <th>Goal</th>
                    <th>Date</th>
                    <th>Progress</th>
                    <th>Status</th>
                </tr>
            </thead>
            <tbody>
                {plans.map((plan) => (
                    <tr key={plan._id}>
                        <td>{plan.user?.name || "Unknown"}</td>
                        <td>{plan.goal?.title || "Deleted Goal"}</td>
                        <td>{new Date(plan.date).toLocaleDateString()}</td>
                        <td>
                            <div className="progress-cell">
                                <span className="percent">{plan.completionPercentage}%</span>
                                <div className="mini-bar">
                                    <div
                                        className="fill"
                                        style={{ width: `${plan.completionPercentage}%`, background: plan.completionPercentage === 100 ? 'var(--accent-emerald)' : 'var(--accent-indigo)' }}
                                    ></div>
                                </div>
                            </div>
                        </td>
                        <td>
                            <span className={`status-pill ${plan.status === 'SUBMITTED' ? 'active' : ''}`}>
                                {plan.status}
                            </span>
                        </td>
                    </tr>
                ))}
            </tbody>
        </table>
        {plans.length === 0 && <div className="empty-state">No activity records found.</div>}
    </motion.div>
));

const StatDetailModal = React.memo(({ detail, onClose }) => (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
        <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-gray-900/20 backdrop-blur-sm"
            onClick={onClose}
        />
        <motion.div
            initial={{ scale: 0.95, opacity: 0, y: 10 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 10 }}
            transition={{ type: "spring", stiffness: 300, damping: 25 }}
            className={`relative bg-[#FDC3A1] border border-[#FDC3A1]/50 w-full max-w-sm rounded-2xl shadow-xl overflow-hidden z-10`}
        >
            <div className={`p-5 border-b border-gray-100 flex justify-between items-center bg-${detail.color}-50`}>
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-lg bg-${detail.color}-100 text-${detail.color}-600`}>
                        {detail.icon}
                    </div>
                    <h3 className="text-lg font-bold text-[#8A244B] tracking-tight">{detail.title}</h3>
                </div>
                <button
                    onClick={onClose}
                    className="p-1.5 rounded-md hover:bg-black/5 text-gray-400 hover:text-gray-600 transition-colors"
                >
                    ✕
                </button>
            </div>
            <div className="p-6">
                {detail.content}
            </div>
            <div className="p-4 border-t border-gray-100 bg-gray-50 text-right">
                <button
                    onClick={onClose}
                    className="text-sm font-semibold text-gray-600 hover:text-gray-900 transition-colors px-4 py-1.5 rounded-lg hover:bg-gray-200/50"
                >
                    Done
                </button>
            </div>
        </motion.div>
    </div>
));

export default AdminDashboard;

const AdminSidebar = React.memo(({ activeTab, onTabSelect, isOpen, setIsOpen }) => (
    <div className={`absolute md:fixed inset-y-0 left-0 top-0 md:top-20 bg-[var(--bg-main)] border-r border-black/5 z-40 transition-all duration-300 ${isOpen ? 'w-64' : 'w-20'} flex flex-col shadow-xl`}>
        <div className="md:hidden flex items-center justify-between p-4 border-b border-black/5">
            <span className={`font-bold text-[#8A244B] ${isOpen ? 'block' : 'hidden'}`}>Admin Menu</span>
            <button onClick={() => setIsOpen(!isOpen)} className="p-2 bg-[var(--button-bg)] rounded-lg text-white">
                <svg className="w-5 h-5 text-[#8A244B]" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={isOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"} />
                </svg>
            </button>
        </div>
        <button onClick={() => setIsOpen(!isOpen)} className="hidden md:flex p-2 absolute -right-3 top-6 bg-[var(--button-bg)] border border-[var(--border-color)] rounded-full text-[#8A244B] shadow-lg hover:scale-110 transition-transform z-50">
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={isOpen ? "M15 19l-7-7 7-7" : "M9 5l7 7-7 7"} />
            </svg>
        </button>
        <div className="flex-1 mt-6 space-y-1.5 px-3 overflow-y-auto w-full">
            <SidebarItem icon={<FiBarChart2 />} label="Overview" isActive={activeTab === 'overview'} onClick={() => onTabSelect('overview')} isOpen={isOpen} />
            <SidebarItem icon={<FiUsers />} label="User Base" isActive={activeTab === 'users'} onClick={() => onTabSelect('users')} isOpen={isOpen} />
            <SidebarItem icon={<FiTarget />} label="Goals" isActive={activeTab === 'goals'} onClick={() => onTabSelect('goals')} isOpen={isOpen} />
            <SidebarItem icon={<FiList />} label="Activity" isActive={activeTab === 'plans'} onClick={() => onTabSelect('plans')} isOpen={isOpen} />
            <SidebarItem icon={<FiTrendingUp />} label="Analytics" isActive={activeTab === 'analytics'} onClick={() => onTabSelect('analytics')} isOpen={isOpen} />
        </div>
    </div>
));

const SidebarItem = React.memo(({ icon, label, isActive, onClick, isOpen }) => (
    <button onClick={onClick} className={`w-full flex items-center p-3 rounded-xl transition-all font-medium ${isActive ? 'bg-[var(--button-bg)] text-[#8A244B] shadow-sm' : 'text-[#8A244B]/70 hover:bg-black/5 hover:text-[#8A244B]'}`}>
        <div className={`text-xl flex-shrink-0 ${isOpen ? 'mr-3' : 'mx-auto'}`}>{icon}</div>
        {isOpen && <span className="whitespace-nowrap overflow-hidden text-ellipsis">{label}</span>}
    </button>
));

const GroupedActivity = React.memo(({ plans }) => {
    const grouped = plans.reduce((acc, plan) => {
        const userName = plan.user?.name || "Unknown";
        if (!acc[userName]) acc[userName] = [];
        acc[userName].push(plan);
        return acc;
    }, {});

    return (
        <motion.div initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 p-6 bg-white/50 backdrop-blur">
            {Object.entries(grouped).map(([name, userPlans]) => (
                <div key={name} className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm hover:shadow-md transition-shadow">
                    <h3 className="font-bold text-[#8A244B] mb-4 flex items-center gap-2 border-b border-gray-100 pb-2"><FiUser className="text-[#FB9B8F]" size={18} />{name}</h3>
                    <div className="space-y-3">
                        {userPlans.map(plan => (
                            <div key={plan._id} className="bg-[#FFF7CD]/40 p-3 rounded-xl border border-[#FDC3A1]/50 text-sm">
                                <div className="flex justify-between items-center mb-1.5">
                                    <span className="font-semibold text-[#8A244B]">{new Date(plan.date).toLocaleDateString()}</span>
                                    <span className="text-[#8A244B] font-bold">{plan.completionPercentage}%</span>
                                </div>
                                <div className="h-1.5 w-full bg-white backdrop-blur rounded-full overflow-hidden border border-[#FDC3A1]/30">
                                    <div className="h-full bg-[#FB9B8F] rounded-full" style={{ width: `${plan.completionPercentage}%` }}></div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            {Object.keys(grouped).length === 0 && <div className="col-span-full py-10 text-center text-gray-500 font-medium">No activity records found matching query.</div>}
        </motion.div>
    )
});
